# Arithmetic specialization for ideals generated by two elements
# Each function returns the resulting ideal when the operation can be done
#   on generators alone, and `nothing` otherwise;
#   the caller then falls back to the matrix path.

################################################################################
#
#  Helpers
#
################################################################################

# Renormalize to the joint modulus:
# At primes of a1, the coprime part f is a unit.
# At the new (added) primes q | m, we have q | f and a1 is a unit.
# We compute a new second generator beta = f*alpha + a1^2 for the modulus m.
# For prime p of a1: v_p(f*alpha + a1^2) = v_p(alpha) = v_p(A) [this is why a1^2, not a1]
# For an added prime q: v_q(f*alpha + a1^2) = v_q(a1^2) = 0 = v_q(A)
function _renormalize_gen_two(alpha::GenOrdElem, a1::RingElem, m::RingElem)
  _, f = ppio(m, a1)
  is_unit(f) && return alpha
  return f*alpha + parent(alpha)(a1^2)
end

function _renormalize_gen_two(I::GenOrdIdl, a1::RingElem, m::RingElem)
  # For principal ideal, the generator remains normal for any (enlarged) modulus
  has_princ_gen(I) && return _princ_gen(I)

  return _renormalize_gen_two(_gen_two(I), a1, m)
end

################################################################################
#
#  Principal Ideals Helpers
#
################################################################################

function _make_principal_ideal(O::GenOrd{S, T}, x::GenOrdElem;
                               ideal_norm = nothing, ideal_minimum = nothing
                              ) where {S, T}
  @hassert :GenOrd 1 parent(x) === O

  I = GenOrdIdl(O)
  I.princ_gen = x
  I.is_principal = 1

  if is_zero(x)
    I.is_zero = 1
    I.norm = zero(base_ring(O))
    I.minimum = zero(base_ring(O))
    return I
  end
  I.is_zero = 2

  if ideal_norm !== nothing
    I.norm = _make_canonical_in(O, ideal_norm)::elem_type(T)
  end

  if ideal_minimum !== nothing
    m = _make_canonical_in(O, ideal_minimum)::elem_type(T)
    I.minimum = m
    I.gen_one = m
    I.gen_two = x
    I.gens_normal = m
  end

  return I
end

function _assure_2_elem_normal_for_principal_ideal(I::GenOrdIdl)
  @hassert :GenOrd 1 has_princ_gen(I)
  # for principal ideals, 2 element form is always created normal
  # TODO: make has_2_elem_normal skip extra checks? make gens_normal stricter?
  has_2_elem(I) && return I

  m = minimum(I; copy = false)
  I.gen_one = m
  I.gen_two = _princ_gen(I)
  I.gens_normal = m
  return I
end

################################################################################
#
#  Multiplication
#
################################################################################

function _mul_impl_princ_gen(a::GenOrdIdl{S, T}, b::GenOrdIdl{S, T}) where {S, T}
  (has_princ_gen(a) && has_princ_gen(b)) || return nothing

  g = _princ_gen(a) * _princ_gen(b)
  if has_norm(a) && has_norm(b)
    n = norm(a; copy = false) * norm(b; copy = false)
    return _make_principal_ideal(order(a), g; ideal_norm = n)
  else
    return _make_principal_ideal(order(a), g)
  end
end

# Reduce gen_two using known minimum: for <m, alpha> we want to reduce alpha.
# Simple-minded <m, alpha mod m> represent same ideal, but might be not normal.
# Instead we compute <m, alpha mod m^2>.
# By normality: v_P(alpha) = v_P(A) <= v_P(m) for P | m
# For any delta in m^2*O: v_P(delta) >= 2*v_P(m) > v_P(m) >= v_P(alpha)
#   giving v_P(alpha + delta) = v_P(alpha) for P | m
# For delta in m*O, we have only v_P(delta) >= v_P(m) >= v_P(alpha);
#   when v_P(delta) = v_P(alpha), alpha + delta might cancel, giving
#   v_P(alpha + delta) > v_P(alpha) = v_P(A), breaking normality
# NOTE: it is enough for m to be a multiple of the minimum, so for example
#   gen_one can be passed here (when we know we have a normal representation).
function _reduce_gen_two_2_elem_normal(alpha::GenOrdElem, m::RingElem)
  return mod(alpha, m^2)
end

function _mul_impl_2_elem_normal(a::GenOrdIdl{S, T}, b::GenOrdIdl{S, T}) where {S, T}
  @hassert :GenOrd 1 has_2_elem_normal(a)
  @hassert :GenOrd 1 has_2_elem_normal(b)

  a1 = has_minimum(a) ? minimum(a; copy = false) : _gen_one(a)
  b1 = has_minimum(b) ? minimum(b; copy = false) : _gen_one(b)
  m = lcm(a1, b1)

  a2 = _gen_two(a)
  b2 = _gen_two(b)
  if _gens_normal(a) != _gens_normal(b)
    a2 = _renormalize_gen_two(a, a1, m)
    b2 = _renormalize_gen_two(b, b1, m)
  end

  O = order(a)

  # (a1, a2) and (b1, b2) are now m-normal over the shared base m
  g1 = _make_canonical_in(O, a1*b1)
  g2 = _reduce_gen_two_2_elem_normal(a2*b2, g1)
  c = ideal(O, g1, g2)

  c.gens_normal = m
  c.norm = _make_canonical_in(O, norm(a; copy = false)*norm(b; copy = false))
  if has_minimum(a) && has_minimum(b) && is_unit(gcd(a1, b1))
    c.minimum = g1
  end

  @hassert :GenOrd 2 defines_2_normal(c)
  return c
end

function _mul_impl_gens(a::GenOrdIdl{S, T}, b::GenOrdIdl{S, T}) where {S, T}
  c = _mul_impl_princ_gen(a, b)
  c === nothing || return c

  O = order(a)
  if is_maximal_known_and_maximal(O)
    # we have already handled principal * principal
    # for mixed case principal * 2-elem-normal make principal have 2-elem-normal representation
    a_can_have_2_elem_normal = has_princ_gen(a) || has_2_elem_normal(a)
    b_can_have_2_elem_normal = has_princ_gen(b) || has_2_elem_normal(b)
    if a_can_have_2_elem_normal && b_can_have_2_elem_normal
      has_princ_gen(a) && _assure_2_elem_normal_for_principal_ideal(a)
      has_princ_gen(b) && _assure_2_elem_normal_for_principal_ideal(b)
      return _mul_impl_2_elem_normal(a, b)
    end
  end

  return nothing
end

###########################################################################################
#
#   Inverse
#
###########################################################################################

# For I = a*O the inverse is (1/a)*O = gamma/d * O with
#   gamma, d = integral_split(a^-1).
# Note that principal ideal is always invertible
function _inv_impl_princ_gen(O::GenOrd, I::GenOrdIdl)
  has_princ_gen(I) || return nothing

  gamma, d = integral_split(inv(data(_princ_gen(I))), O)

  J = if has_norm(I)
    # N(gamma) = N(d/a) = d^n / N(I)
    n = divexact(d^degree(O), norm(I; copy = false))
    _make_principal_ideal(O, gamma; ideal_norm = n)
  else
    _make_principal_ideal(O, gamma)
  end

  return fractional_ideal(J, d)
end

# For A = <m, alpha> with m = minimum(A) in m-normal two-element representation
#   A^{-1} = O + beta*O, with beta = d_c * alpha^{-1}, d_c = part of denom(alpha^{-1}) coprime to m.
# We compute this ideal as <d_m, gamma>/d_m, with
#   gamma = numerator(alpha^{-1}, O) = d*alpha^{-1}; d = denom(alpha^{-1})
#   d_m = part of denom(alpha^{-1}) supported at m.
# We then have <d_m, gamma> = d_m*A^{-1} normal
function _inv_impl_2_elem_normal(O::GenOrd, A::GenOrdIdl)
  @hassert :GenOrd 1 has_2_elem_normal(A)

  m = minimum(A; copy = false)
  is_unit(m) && return fractional_ideal(A)

  gamma, d = integral_split(inv(data(_gen_two(A))), O)
  d_m = _make_canonical_in(O, ppio(d, m)[1])

  Ai = ideal(O, d_m, _reduce_gen_two_2_elem_normal(gamma, d_m))
  Ai.gens_normal = d_m
  Ai.norm = _make_canonical_in(O, divexact(d_m^degree(O), norm(A; copy = false)))
  @hassert :GenOrd 2 defines_2_normal(Ai)
  return fractional_ideal(Ai, d_m)
end
